import { useState, useRef } from "react";

import { useTranslations } from "next-intl";

import { motion } from "motion/react";



// ─── Base64 Image Assets ────────────────────────────────────────────────────
// Replace the empty string after 'base64,' with the actual base64 data for each image.

// /images/banner.jpg  ← gambar hero banner (isi base64 di sini)
const IMG_BANNER = "data:image/jpeg;base64,";

const IMG_SPEAKER_1 = "data:image/jpeg;base64,";

const IMG_SPEAKER_2 = "data:image/webp;base64,";

const IMG_SPEAKER_3 = "data:image/jpeg;base64,";

const IMG_SPEAKER_4 = "data:image/jpeg;base64,";

const IMG_SPEAKER_5 = "data:image/jpeg;base64,";

const IMG_SPEAKER_6 = "data:image/jpeg;base64,";

const IMG_SPEAKER_7 = "data:image/jpeg;base64,";

const IMG_SPEAKER_8 = "data:image/png;base64,";

const IMG_SPEAKER_9 = "data:image/jpeg;base64,";

const IMG_SPEAKER_10 = "data:image/jpeg;base64,";

const IMG_QR_CODE = "data:image/png;base64,";

const IMG_GROUP_1 = "data:image/jpeg;base64,";

const speakerList = [

  { id: 1, name: "Andes Hamuraby Rozak, Ph.D",              roleKey: "sp1Role", img: IMG_SPEAKER_1 },

  { id: 2, name: "Prof. Gilberto Camara",               roleKey: "sp2Role", img: IMG_SPEAKER_2 },

  { id: 3, name: "Asep Hidayat, M.Agr, Ph.D",                      roleKey: "sp3Role", img: IMG_SPEAKER_3 },

  { id: 4, name: "Ping Yowargana",  roleKey: "sp4Role", img: IMG_SPEAKER_4 },

  { id: 5, name: "Andree Ekadinata",       roleKey: "sp5Role", img: IMG_SPEAKER_5 },

  { id: 6, name: "Harry Aksomo",      roleKey: "sp6Role", img: IMG_SPEAKER_6 },

  { id: 7, name: "Dony Indiarto",                   roleKey: "sp7Role", img: IMG_SPEAKER_7 },

  { id: 8, name: "Maria Adelia Widijanto",                roleKey: "sp8Role", img: IMG_SPEAKER_8 },

  { id: 9, name: "Arga Pandiwijaya",                   roleKey: "sp9Role", img: IMG_SPEAKER_9 },

  { id: 10, name: "Nurhayatun Nafsiyah",                   roleKey: "sp10Role", img: IMG_SPEAKER_10 },

];




// ─── Hero (homepage-style banner) ────────────────────────────────────────────



function HeroSection() {

  const t = useTranslations("EventPage");



  return (

    <section

      id="beranda"

      style={{ position: "relative", overflow: "hidden" }}

    >

      {/* Full-width image area — set IMG_BANNER di atas untuk mengganti gambar */}

      <div

        style={{

          position: "relative",

          width: "100%",

          minHeight: "520px",

          background: IMG_BANNER ? `url('${IMG_BANNER}') center/cover no-repeat` : "#e8e8e8",

          display: "flex",

          alignItems: "flex-end",

        }}

      >

        {/* Overlay gelap supaya teks tetap terbaca di atas gambar */}

        <div

          style={{

            position: "absolute",

            inset: 0,

            background: IMG_BANNER

              ? "linear-gradient(to top, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0.15) 60%, transparent 100%)"

              : "none",

            pointerEvents: "none",

          }}

        />

        {/* Text overlay — bottom-left, matching reference image layout */}

        <div

          style={{

            position: "relative",

            zIndex: 2,

            width: "100%",

            padding: "clamp(32px, 5vw, 72px) clamp(24px, 6vw, 80px)",

          }}

        >

          {/* Eyebrow — small, normal weight */}

          <motion.p

            initial={{ opacity: 0, y: 16 }}

            animate={{ opacity: 1, y: 0 }}

            transition={{ delay: 0.1, duration: 0.6 }}

            style={{

              color: IMG_BANNER ? "rgba(255,255,255,0.85)" : "#1a1a1a",

              fontSize: "clamp(12px, 1.2vw, 15px)",

              fontWeight: 400,

              letterSpacing: "0.01em",

              fontFamily: "var(--font-pjs)",

              margin: 0,

              marginBottom: "clamp(8px, 1vw, 14px)",

            }}

          >

            {t("meta.eyebrow")}

          </motion.p>

          {/* Main title — large, bold, brand color */}

          <motion.h1

            initial={{ opacity: 0, y: 20 }}

            animate={{ opacity: 1, y: 0 }}

            transition={{ delay: 0.2, duration: 0.7 }}

            style={{

              color: IMG_BANNER ? "#ffffff" : "#1a4fa3",

              fontSize: "clamp(26px, 3.5vw, 48px)",

              fontWeight: 700,

              lineHeight: 1.2,

              margin: 0,

              marginBottom: "clamp(10px, 1.2vw, 18px)",

              fontFamily: "var(--font-pjs)",

              maxWidth: "700px",

            }}

          >

            {t("meta.title")}

          </motion.h1>

          {/* Subtitle — medium, dark, normal weight */}

          <motion.p

            initial={{ opacity: 0, y: 16 }}

            animate={{ opacity: 1, y: 0 }}

            transition={{ delay: 0.32, duration: 0.7 }}

            style={{

              color: IMG_BANNER ? "rgba(255,255,255,0.92)" : "#1a1a1a",

              fontSize: "clamp(14px, 1.6vw, 20px)",

              fontWeight: 600,

              lineHeight: 1.4,

              margin: 0,

              fontFamily: "var(--font-pjs)",

              maxWidth: "620px",

            }}

          >

            {t("meta.subtitle")}

          </motion.p>

        </div>

      </div>

    </section>

  );

}



// ─── Summary ─────────────────────────────────────────────────────────────────


function SummarySection() {
  const t = useTranslations("EventPage");

  // ─── DATA LINK MATERI PRESENTASI ───
  // Silakan ganti URL di bawah ini dengan tautan Google Drive / file asli Anda
  const materialsList = [
    { id: 1, link: "https://drive.google.com/file/d/13jG6QwBhRATembadDNzRA7pw3aXXFSS6/view?usp=sharing" },
    { id: 2, link: "https://drive.google.com/file/d/10J-fMUEZYATQtRwuldu5c4Xd_K4Fm0-z/view?usp=sharing" },
    { id: 3, link: "https://drive.google.com/file/d/1u-riOUPFPjjDxeI7mx0_mQILrTDfqsCm/view?usp=sharing" },
  ];

  return (
    <section id="summary" style={{ padding: "100px 24px", background: "linear-gradient(180deg, #ffffff 0%, #fdf8fa 100%)" }}>
      <div style={{ maxWidth: 1200, margin: "0 auto" }}>
        
        {/* Layout Utama: 2 Kolom Responsif */}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: "64px", alignItems: "start" }}>
          
          {/* ─── KOLOM KIRI: GAMBAR (Sticky) ─── */}
          <div style={{ position: "sticky", top: "120px" }}>
            <div style={{
              borderRadius: "24px",
              overflow: "hidden",
              boxShadow: "0 24px 48px rgba(204, 71, 120, 0.08)",
              border: "1px solid rgba(255, 255, 255, 0.5)",
              background: "white"
            }}>
              <img 
                src={IMG_GROUP_1} 
                alt="Event Group" 
                style={{ width: "100%", height: "100%", objectFit: "cover", aspectRatio: "4/3", display: "block" }} 
              />
            </div>
          </div>

          {/* ─── KOLOM KANAN: KONTEN & TEKS ─── */}
          <div>
            <p style={{ color: "#cc4778", fontWeight: 800, fontSize: 14, letterSpacing: "0.15em", textTransform: "uppercase", marginBottom: 12, fontFamily: "var(--font-pjs)" }}>
              {t("summary.label")}
            </p>
            <h2 style={{ fontSize: "clamp(28px,3.5vw,40px)", fontWeight: 700, color: "#1a1a1a", letterSpacing: "-0.02em", marginBottom: 40, fontFamily: "var(--font-pjs)" }}>            
              {t("summary.title")} <span style={{ color: "#cc4778" }}>{t("summary.titleHighlight")}</span>
            </h2>

            {/* Paragraf */}
            <div style={{ display: "flex", flexDirection: "column", gap: 20, marginBottom: 48 }}>
              <p style={{ color: "#4a4a4a", lineHeight: 1.8, fontSize: 18, margin: 0, fontFamily: "var(--font-pjs)" }}>{t("summary.p1")}</p>
              <p style={{ color: "#4a4a4a", lineHeight: 1.8, fontSize: 18, margin: 0, fontFamily: "var(--font-pjs)" }}>{t("summary.p2")}</p>
              <p style={{ color: "#4a4a4a", lineHeight: 1.8, fontSize: 18, margin: 0, fontFamily: "var(--font-pjs)" }}>{t("summary.p3")}</p>
              <p style={{ color: "#4a4a4a", lineHeight: 1.8, fontSize: 18, margin: 0, fontFamily: "var(--font-pjs)" }}>
                {t.rich("summary.p4", {
                  torlink: (chunks) => (
                    <a 
                      href={t("summary.torUrl")} 
                      target="_blank" 
                      rel="noopener noreferrer" 
                      style={{ color: "#cc4778", textDecoration: "none", borderBottom: "2px solid #cc4778", fontWeight: 700, transition: "opacity 0.2s" }}
                    >
                      {chunks}
                    </a>
                  )
                })}
              </p>
            </div>

            {/* ─── KARTU INFORMASI & MATERI (Glassmorphism) ─── */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 20 }}>
              
              {/* Kartu Lokasi & Tanggal (Setengah Lebar) */}
              {[
                { emoji: "📍", label: t("summary.whereLabel"), value: t("summary.whereValue") },
                { emoji: "📅", label: t("summary.whenLabel"), value: t("summary.whenValue") },
              ].map(({ emoji, label, value }) => (
                <div
                  key={label}
                  style={{
                    display: "flex", 
                    flexDirection: "column",
                    gap: 16, 
                    background: "rgba(255, 255, 255, 0.7)",
                    backdropFilter: "blur(12px)",
                    WebkitBackdropFilter: "blur(12px)",
                    borderRadius: "20px", 
                    padding: "24px",
                    boxShadow: "0 8px 32px rgba(204, 71, 120, 0.05)", 
                    border: "1px solid rgba(255, 255, 255, 0.8)",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "flex-start", gap: 16 }}>
                    <div style={{ width: 48, height: 48, borderRadius: "14px", background: "rgba(204, 71, 120, 0.1)", color: "#cc4778", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 22 }}>
                      {emoji}
                    </div>
                    <div style={{ flex: 1 }}>
                      <p style={{ fontWeight: 700, fontSize: 12, color: "#888", textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 6px", fontFamily: "var(--font-pjs)" }}>{label}</p>
                      <p style={{ fontSize: 16, fontWeight: 700, color: "#1a1a1a", margin: 0, fontFamily: "var(--font-pjs)", lineHeight: 1.4 }}>{value}</p>
                    </div>
                  </div>
                </div>
              ))}

              {/* ─── KARTU ONLINE / ZOOM (Lebar Penuh, QR Tengah) ─── */}
              <div
                style={{
                  gridColumn: "1 / -1", // Menjadikan kotak memanjang penuh
                  display: "flex", 
                  flexDirection: "column",
                  gap: 16, 
                  background: "rgba(255, 255, 255, 0.7)",
                  backdropFilter: "blur(12px)",
                  WebkitBackdropFilter: "blur(12px)",
                  borderRadius: "20px", 
                  padding: "24px",
                  boxShadow: "0 8px 32px rgba(204, 71, 120, 0.05)", 
                  border: "1px solid rgba(255, 255, 255, 0.8)",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                  <div style={{ width: 48, height: 48, borderRadius: "14px", background: "rgba(204, 71, 120, 0.1)", color: "#cc4778", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 22 }}>
                    💻
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontWeight: 700, fontSize: 12, color: "#888", textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 6px", fontFamily: "var(--font-pjs)" }}>
                      {t("summary.zoomLabel")}
                    </p>
                    <p style={{ fontSize: 16, fontWeight: 700, color: "#1a1a1a", margin: 0, fontFamily: "var(--font-pjs)", lineHeight: 1.4 }}>
                      {t("summary.zoomValue")}
                    </p>
                  </div>
                </div>
                
                {/* QR Code Besar di Tengah */}
                <div style={{ marginTop: 16, paddingTop: 24, borderTop: "1px dashed rgba(204,71,120,0.2)", display: "flex", justifyContent: "center" }}>
                  <img 
                    src={IMG_QR_CODE} // Pastikan variabel IMG_QR_CODE sudah ada
                    alt={`QR Code Zoom`} 
                    style={{ 
                      width: "100%", 
                      maxWidth: "240px", // Ukuran diperbesar
                      height: "auto", 
                      borderRadius: "16px", 
                      border: "6px solid white", 
                      boxShadow: "0 8px 24px rgba(0,0,0,0.08)",
                      display: "block"
                    }} 
                  />
                </div>
              </div>

              {/* ─── KARTU: KUMPULAN MATERI PRESENTASI (Lebar Penuh) ─── */}
              <div
                style={{
                  gridColumn: "1 / -1", 
                  display: "flex", 
                  flexDirection: "column",
                  gap: 16, 
                  background: "rgba(255, 255, 255, 0.7)",
                  backdropFilter: "blur(12px)",
                  WebkitBackdropFilter: "blur(12px)",
                  borderRadius: "20px", 
                  padding: "24px",
                  boxShadow: "0 8px 32px rgba(204, 71, 120, 0.05)", 
                  border: "1px solid rgba(255, 255, 255, 0.8)",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
                  <div style={{ width: 48, height: 48, borderRadius: "14px", background: "rgba(204, 71, 120, 0.1)", color: "#cc4778", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, fontSize: 22 }}>
                    📁
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontWeight: 700, fontSize: 12, color: "#888", textTransform: "uppercase", letterSpacing: "0.05em", margin: "0 0 6px", fontFamily: "var(--font-pjs)" }}>
                      {t("summary.materials.label") || "UNDUHAN"}
                    </p>
                    <p style={{ fontSize: 16, fontWeight: 700, color: "#1a1a1a", margin: 0, fontFamily: "var(--font-pjs)", lineHeight: 1.4 }}>
                      {t("summary.materials.title")} <span style={{ color: "#cc4778" }}>{t("summary.materials.titleHighlight")}</span>
                    </p>
                  </div>
                </div>

                {/* List File Materi menggunakan materialsList */}
                <div style={{ marginTop: 8, paddingTop: 16, borderTop: "1px dashed rgba(204,71,120,0.2)", display: "flex", flexDirection: "column", gap: 12 }}>
                  {materialsList.map((mat) => (
                    <a
                      key={`mat-${mat.id}`}
                      href={mat.link} // Tautan diambil secara dinamis dari array materialsList
                      target="_blank"
                      rel="noopener noreferrer"
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 16,
                        textDecoration: "none",
                        color: "#1a1a1a",
                        padding: "12px 16px",
                        background: "rgba(255,255,255,0.8)",
                        borderRadius: "12px",
                        border: "1px solid rgba(0,0,0,0.04)",
                        transition: "all 0.2s ease",
                      }}
                      onMouseOver={(e) => {
                        e.currentTarget.style.borderColor = "rgba(204,71,120,0.3)";
                        e.currentTarget.style.boxShadow = "0 4px 12px rgba(204,71,120,0.08)";
                        e.currentTarget.style.transform = "translateY(-2px)";
                      }}
                      onMouseOut={(e) => {
                        e.currentTarget.style.borderColor = "rgba(0,0,0,0.04)";
                        e.currentTarget.style.boxShadow = "none";
                        e.currentTarget.style.transform = "translateY(0)";
                      }}
                    >
                      <div style={{ fontSize: 20 }}>📄</div>
                      <div style={{ flex: 1 }}>
                        <p style={{ margin: "0 0 4px", fontSize: 14, fontWeight: 700, fontFamily: "var(--font-pjs)", lineHeight: 1.3, color: "#111" }}>
                          {t(`summary.materials.mat${mat.id}Title` as any)}
                        </p>
                        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                          <span style={{ fontSize: 10, fontWeight: 800, background: "#f5f5f5", color: "#666", padding: "2px 6px", borderRadius: 4, letterSpacing: "0.05em", fontFamily: "var(--font-pjs)" }}>
                            {t(`summary.materials.mat${mat.id}Type` as any)}
                          </span>
                          <span style={{ fontSize: 12, color: "#888", fontFamily: "var(--font-pjs)" }}>
                            {t(`summary.materials.mat${mat.id}Speaker` as any)}
                          </span>
                        </div>
                      </div>
                      <div style={{ width: 32, height: 32, borderRadius: "50%", background: "rgba(204,71,120,0.1)", color: "#cc4778", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: "bold" }}>
                        ↓
                      </div>
                    </a>
                  ))}
                </div>
              </div>

            </div>

          </div>
        </div>

      </div>
    </section>
  );
}


// ─── Press Release ────────────────────────────────────────────────────────────

function PressReleaseSection() {
  const t = useTranslations("EventPage");
  const [expanded, setExpanded] = useState(false);

  return (
    <section id="press-release" style={{ padding: "80px 24px", background: "white" }}>
      <div style={{ maxWidth: 1200, margin: "0 auto" }}>

        {/* Header */}
        <div style={{ marginBottom: 48 }}>
          <p style={{ color: "#cc4778", fontWeight: 700, fontSize: 14, letterSpacing: "0.14em", textTransform: "uppercase", marginBottom: 8, fontFamily: "var(--font-pjs)" }}>
            {t("pressRelease.label")}
          </p>
          <h2 style={{ fontSize: "clamp(28px,3.5vw,40px)", fontWeight: 700, color: "#1a1a1a", letterSpacing: "-0.02em", margin: 0, fontFamily: "var(--font-pjs)" }}>
            {t("pressRelease.title")}{" "}
            <span style={{ color: "#cc4778" }}>{t("pressRelease.titleHighlight")}</span>
          </h2>
        </div>

        {/* Main card */}
        <div
          style={{
            background: "linear-gradient(135deg, #fdf6f9 0%, #f9f4f6 50%, #fef9fb 100%)",
            borderRadius: 24,
            border: "1px solid #f0dce6",
            overflow: "hidden",
            boxShadow: "0 8px 40px rgba(204,71,120,0.08)",
          }}
        >
          {/* Top accent bar */}
          <div style={{ height: 4, background: "linear-gradient(90deg, #cc4778 0%, #e8729c 50%, #1a4fa3 100%)" }} />

          <div style={{ padding: "clamp(28px, 4vw, 48px)" }}>

            {/* Date badge + headline */}
            <div style={{ display: "flex", alignItems: "flex-start", gap: 20, marginBottom: 32, flexWrap: "wrap" }}>
              <div
                style={{
                  background: "#cc4778",
                  color: "white",
                  borderRadius: 12,
                  padding: "8px 16px",
                  fontSize: 14,
                  fontWeight: 700,
                  letterSpacing: "0.08em",
                  fontFamily: "var(--font-pjs)",
                  whiteSpace: "nowrap",
                  flexShrink: 0,
                  alignSelf: "flex-start",
                  marginTop: 4,
                }}
              >
                {t("pressRelease.date")}
              </div>
            </div>

            {/* Body paragraphs (Awal) */}
            <div style={{ display: "grid", gridTemplateColumns: expanded ? "1fr" : "1fr 1fr", gap: "0 40px" }} className="pr-body-grid">
              <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                {t("pressRelease.body1")}
              </p>
              <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                {t("pressRelease.body2")}
              </p>
            </div>

            {/* Expanded content */}
            {expanded && (
              <>
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body3")}
                </p>
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body4")}
                </p>

                {/* Quote 1 */}
                <div
                  style={{
                    borderLeft: "4px solid #cc4778",
                    background: "rgba(204,71,120,0.04)",
                    borderRadius: "0 12px 12px 0",
                    padding: "20px 24px",
                    margin: "8px 0 28px",
                  }}
                >
                  <p
                    style={{
                      color: "#1a1a1a",
                      fontSize: "clamp(20px, 1.4vw, 17px)",
                      fontStyle: "italic",
                      lineHeight: 1.7,
                      margin: "0 0 12px",
                      fontFamily: "var(--font-pjs)",
                    }}
                  >
                    "{t("pressRelease.quote1Text")}"
                  </p>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <div style={{ width: 32, height: 2, background: "#cc4778", borderRadius: 2 }} />
                    <div>
                      <span style={{ fontWeight: 700, fontSize: 14, color: "#cc4778", fontFamily: "var(--font-pjs)" }}>
                        {t("pressRelease.quote1Author")}
                      </span>
                      <span style={{ color: "#525252", fontSize: 14, fontFamily: "var(--font-pjs)", marginLeft: 6 }}>
                        — {t("pressRelease.quote1Role")}
                      </span>
                    </div>
                  </div>
                </div>

                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body5")}
                </p>

                {/* Quote 2 */}
                <div
                  style={{
                    borderLeft: "4px solid #1a4fa3",
                    background: "rgba(26,79,163,0.04)",
                    borderRadius: "0 12px 12px 0",
                    padding: "20px 24px",
                    margin: "8px 0 28px",
                  }}
                >
                  <p
                    style={{
                      color: "#1a1a1a",
                      fontSize: "clamp(20px, 1.4vw, 17px)",
                      fontStyle: "italic",
                      lineHeight: 1.7,
                      margin: "0 0 12px",
                      fontFamily: "var(--font-pjs)",
                    }}
                  >
                    "{t("pressRelease.quote2Text")}"
                  </p>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <div style={{ width: 32, height: 2, background: "#1a4fa3", borderRadius: 2 }} />
                    <div>
                      <span style={{ fontWeight: 700, fontSize: 14, color: "#1a4fa3", fontFamily: "var(--font-pjs)" }}>
                        {t("pressRelease.quote2Author")}
                      </span>
                      <span style={{ color: "#525252", fontSize: 14, fontFamily: "var(--font-pjs)", marginLeft: 6 }}>
                        — {t("pressRelease.quote2Role")}
                      </span>
                    </div>
                  </div>
                </div>

                {/* --- Tambahan 6 Paragraf Baru (Body 7 - Body 12) --- */}
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body6")}
                </p>
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body7")}
                </p>
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body8")}
                </p>
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body9")}
                </p>
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body10")}
                </p>
                <p style={{ color: "#555", lineHeight: 1.85, fontSize: 18, margin: "0 0 20px", fontFamily: "var(--font-pjs)" }}>
                  {t("pressRelease.body11")}
                </p>

                {/* Contact */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 12,
                    background: "white",
                    borderRadius: 12,
                    padding: "16px 20px",
                    border: "1px solid #f0dce6",
                    marginTop: 8,
                    width: "fit-content",
                  }}
                >
                  <div style={{ width: 36, height: 36, borderRadius: "50%", background: "#faedf2", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 16 }}>✉️</div>
                  <div>
                    <p style={{ margin: 0, fontSize: 11, fontWeight: 700, color: "#cc4778", letterSpacing: "0.1em", textTransform: "uppercase", fontFamily: "var(--font-pjs)" }}>
                      {t("pressRelease.contactLabel")}
                    </p>
                    <p style={{ margin: "2px 0 0", fontSize: 13, color: "#1a1a1a", fontFamily: "var(--font-pjs)" }}>
                      {t("pressRelease.contactTeam")} —{" "}
                      <a href={`mailto:${t("pressRelease.contactEmail")}`} style={{ color: "#cc4778", textDecoration: "none", fontWeight: 600 }}>
                        {t("pressRelease.contactEmail")}
                      </a>
                    </p>
                  </div>
                </div>
              </>
            )}

            {/* Actions */}
            <div style={{ display: "flex", gap: 12, marginTop: 32, flexWrap: "wrap", alignItems: "center" }}>
              <button
                onClick={() => setExpanded(!expanded)}
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 8,
                  background: expanded ? "#f0dce6" : "#cc4778",
                  color: expanded ? "#cc4778" : "white",
                  border: "none",
                  borderRadius: 50,
                  padding: "12px 24px",
                  fontSize: 14,
                  fontWeight: 700,
                  cursor: "pointer",
                  fontFamily: "var(--font-pjs)",
                  transition: "all 0.2s",
                  letterSpacing: "0.01em",
                }}
              >
                <span>{expanded ? "↑" : "↓"}</span>
                {expanded ? (
                  <span>{t("pressRelease.collapse")}</span>
                ) : (
                  <span>{t("pressRelease.readMore")}</span>
                )}
              </button>
            </div>

          </div>
        </div>
      </div>
    </section>
  );
}



// ─── Speakers ─────────────────────────────────────────────────────────────────



function SpeakersSection() {

  const t = useTranslations("EventPage");

  const sliderRef = useRef<HTMLDivElement>(null);



  const scroll = (dir: "left" | "right") => {

    if (!sliderRef.current) return;

    const itemW = sliderRef.current.querySelector<HTMLElement>(".speaker-card")?.offsetWidth ?? 260;

    sliderRef.current.scrollBy({ left: dir === "right" ? itemW + 16 : -(itemW + 16), behavior: "smooth" });

  };



  return (

    <section id="speakers" style={{ padding: "80px 0", background: "#f9f4f6" }}>

      <div style={{ maxWidth: 1200, margin: "0 auto", padding: "0 24px" }}>

        <p style={{ color: "#cc4778", fontWeight: 700, fontSize: 14, letterSpacing: "0.14em", textTransform: "uppercase", marginBottom: 8, fontFamily: "var(--font-pjs)" }}>

          {t("speakers.label")}

        </p>

        <h2 style={{ fontSize: "clamp(28px,3.5vw,40px)", fontWeight: 700, color: "#1a1a1a", letterSpacing: "-0.02em", marginBottom: 40, fontFamily: "var(--font-pjs)" }}>

          {t("speakers.title")}{" "}

          <span style={{ color: "#cc4778" }}>{t("speakers.titleHighlight")}</span>

        </h2>

      </div>



      <div style={{ position: "relative", padding: "0 24px" }}>

        <button

          onClick={() => scroll("left")}

          style={{ position: "absolute", left: 4, top: "50%", transform: "translateY(-50%)", zIndex: 10, background: "#cc4778", color: "white", border: "none", borderRadius: "50%", width: 44, height: 44, cursor: "pointer", fontSize: 18, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 4px 12px rgba(204,71,120,0.35)" }}

        >

          ‹

        </button>



        <div

          ref={sliderRef}

          style={{ display: "flex", overflowX: "auto", gap: 16, scrollBehavior: "smooth", scrollbarWidth: "none", padding: "8px 32px" }}

        >

          {speakerList.map((sp) => (

            <div

              key={sp.id}

              className="speaker-card"

              style={{ flex: "0 0 260px", borderRadius: 20, overflow: "hidden", position: "relative", cursor: "pointer", transition: "transform 0.3s, box-shadow 0.3s" }}

              onMouseEnter={(e) => {

                (e.currentTarget as HTMLElement).style.transform = "translateY(-8px)";

                (e.currentTarget as HTMLElement).style.boxShadow = "0 16px 40px rgba(204,71,120,0.25)";

              }}

              onMouseLeave={(e) => {

                (e.currentTarget as HTMLElement).style.transform = "translateY(0)";

                (e.currentTarget as HTMLElement).style.boxShadow = "none";

              }}

            >

              <img src={sp.img} alt={sp.name} style={{ width: "100%", aspectRatio: "3/4", objectFit: "cover", display: "block" }} />

              <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, background: "linear-gradient(to top, rgba(26,26,26,0.92) 0%, transparent 100%)", padding: "40px 16px 16px" }}>

                <p style={{ color: "white", fontWeight: 700, fontSize: 14, margin: 0, fontFamily: "var(--font-pjs)" }}>{sp.name}</p>

                <p style={{ color: "rgba(255,255,255,0.75)", fontSize: 11, margin: "4px 0 0", lineHeight: 1.4, fontFamily: "var(--font-pjs)" }}>

                  {t(`speakerRoles.${sp.roleKey}` as any)}

                </p>

              </div>

            </div>

          ))}

        </div>



        <button

          onClick={() => scroll("right")}

          style={{ position: "absolute", right: 4, top: "50%", transform: "translateY(-50%)", zIndex: 10, background: "#cc4778", color: "white", border: "none", borderRadius: "50%", width: 44, height: 44, cursor: "pointer", fontSize: 18, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 4px 12px rgba(204,71,120,0.35)" }}

        >

          ›

        </button>

      </div>

    </section>

  );

}



// ─── Agenda ───────────────────────────────────────────────────────────────────



function AgendaSection() {

  const t = useTranslations("EventPage");



  const agendaItems = [

    { time: "08:30 – 09:00", title: t('agenda.item1Title'), desc: null, speakers: [] as { img: string; name: string }[] },

    { time: "09:00 – 09:25", title: t('agenda.item2Title'), desc: null, speakers: [
        { img: "data:image/jpeg;base64,", name: "Andree Ekadinata" },
        { img: "data:image/jpeg;base64,", name: "Asep Hidayat" },
      ]
    },

    {
      time: "09:25 – 10:15", title: t('agenda.item3Title'), desc: null,
      speakers: [
        { img: "data:image/jpeg;base64,", name: "Andes Hamuraby Rozak" },
        { img: "data:image/webp;base64,", name: "Prof. Gilberto Camara" },
      ],
    },

    { time: "10:15 – 11:00", title: t('agenda.item4Title'), desc: null, speakers: [
        { img: "data:image/jpeg;base64,", name: "Ping Yowargana" },
      ]
    },

    {
      time: "11:00 – 12:15", title: t('agenda.item5Title'), desc: null,
      speakers: [
        { img: "data:image/jpeg;base64,", name: "Harry Aksomo" },
        { img: "", name: "Komunitas Karsa Bentala" },
      ],
    },

    { time: "13:15 – 14:15", title: t('agenda.item6Title'), desc: null, speakers: [
        { img: "data:image/jpeg;base64,", name: "Dony Indiarto" },
        { img: "data:image/png;base64,", name: "Maria Adelia Widijanto" },
      ]
    },

    {
      time: "14:15 – 16:15", title: t('agenda.item5Desc'), desc: null,
      speakers: [
        { img: "data:image/jpeg;base64,", name: "Arga Pandiwijaya" },
        { img: "data:image/jpeg;base64,", name: "Nurhayatun Nafsiyah" },
      ],
    },

    { time: "16:15 – 16:30", title: t('agenda.closing'), desc: null, speakers: [] },

  ];



  return (

    <section id="agenda" style={{ padding: "80px 24px", background: "white" }}>

      <div style={{ maxWidth: 900, margin: "0 auto" }}>

        <div style={{ textAlign: "center", marginBottom: 56 }}>

          <p style={{ color: "#cc4778", fontWeight: 700, fontSize: 14, letterSpacing: "0.14em", textTransform: "uppercase", marginBottom: 8, fontFamily: "var(--font-pjs)" }}>

            {t("agenda.label")}

          </p>

          <h2 style={{ fontSize: "clamp(28px,3.5vw,40px)", fontWeight: 700, color: "#1a1a1a", letterSpacing: "-0.02em", fontFamily: "var(--font-pjs)" }}>

            <span style={{ color: "#cc4778" }}>{t("agenda.title")}</span>{" "}

            {t("agenda.titleHighlight")}

          </h2>

        </div>



        <div style={{ position: "relative", paddingLeft: 32, borderLeft: "2px solid #f0dce6" }}>

          {agendaItems.map((item, i) => (

            <div key={i} style={{ position: "relative", marginBottom: i < agendaItems.length - 1 ? 24 : 0 }}>

              <div style={{ position: "absolute", left: -43, top: 20, width: 20, height: 20, borderRadius: "50%", background: "#cc4778", border: "4px solid white", boxShadow: "0 0 0 2px #cc4778" }} />

              <div style={{ background: "white", borderRadius: 20, padding: "24px 28px", boxShadow: "0 4px 20px rgba(0,0,0,0.07)", border: "1px solid #f0dce6" }}>

                <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", flexWrap: "wrap", gap: 8, marginBottom: item.desc || item.speakers.length ? 12 : 0 }}>

                  <h4 style={{ fontWeight: 700, fontSize: 16, color: "#1a1a1a", margin: 0, fontFamily: "var(--font-pjs)" }}>

                    {item.title}

                  </h4>

                  <span style={{ background: "#faedf2", color: "#cc4778", borderRadius: 20, padding: "4px 12px", fontSize: 12, fontWeight: 600, whiteSpace: "nowrap", fontFamily: "var(--font-pjs)" }}>

                    🕐 {item.time}

                  </span>

                </div>



                {item.desc && (

                  <p style={{ fontSize: 14, color: "#666", margin: "0 0 16px", fontFamily: "var(--font-pjs)" }}>

                    {item.desc}

                  </p>

                )}



                {item.speakers.length > 0 && (

                  <div style={{ display: "flex", flexDirection: "column", gap: 12, marginTop: 8 }}>

                    {item.speakers.map((sp, si) => (

                      <div key={si} style={{ display: "flex", alignItems: "center", gap: 12 }}>

                        {sp.img && (
                          <img src={sp.img} alt={sp.name} style={{ width: 44, height: 44, borderRadius: "50%", objectFit: "cover", flexShrink: 0, border: "2px solid #f0dce6" }} />
                        )}

                        {!sp.img && (
                          <div style={{ width: 44, height: 44, borderRadius: "50%", background: "#f0dce6", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>
                            🧑
                          </div>
                        )}

                        <div>

                          <p style={{ margin: 0, fontWeight: 600, fontSize: 13, color: "#cc4778", fontFamily: "var(--font-pjs)" }}>{sp.name}</p>

                        </div>

                      </div>

                    ))}

                  </div>

                )}

              </div>

            </div>

          ))}

        </div>

      </div>

    </section>

  );

}



// ─── Page ─────────────────────────────────────────────────────────────────────



export default function EventPage() {

  return (

    <>

      <style>{`

        .speaker-card::-webkit-scrollbar { display: none; }



        .event-hero-grid {

          display: grid;

          grid-template-columns: 1fr 1fr;

          gap: 48px;

          align-items: center;

        }



        .event-ringkasan-grid {

          display: grid;

          grid-template-columns: 1fr 1fr;

          gap: 60px;

          align-items: start;

        }

        .event-ringkasan-photos { display: block; }



        @media (max-width: 768px) {

          .event-ringkasan-grid { grid-template-columns: 1fr; }

          .event-ringkasan-photos { display: block; }

          .pr-body-grid { grid-template-columns: 1fr !important; }

        }

      `}</style>



      <main>

        <HeroSection />

        <SummarySection />

        <PressReleaseSection />

        <SpeakersSection />

        <AgendaSection />

      </main>

    </>

  );

}